-- V90.fl: Reliability Governance Learning Outcome Closure & Knowledge Standardization
-- Schema target: 238
CREATE TABLE IF NOT EXISTS maintenance_reliability_governance_learning_closure (closure_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, period_key TEXT NOT NULL, execution_count INTEGER NOT NULL DEFAULT 0, completed_count INTEGER NOT NULL DEFAULT 0, benefit_review_count INTEGER NOT NULL DEFAULT 0, effective_count INTEGER NOT NULL DEFAULT 0, ineffective_count INTEGER NOT NULL DEFAULT 0, followup_count INTEGER NOT NULL DEFAULT 0, average_score_delta NUMERIC NOT NULL DEFAULT 0, closure_assessment TEXT NOT NULL DEFAULT 'INCOMPLETE', closure_note TEXT NOT NULL, evidence_note TEXT NOT NULL, closed_by TEXT NOT NULL, closed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,entity_id,period_key));
CREATE TABLE IF NOT EXISTS maintenance_reliability_governance_learning_knowledge (knowledge_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, period_key TEXT NOT NULL, source_execution_id TEXT, source_benefit_id TEXT, knowledge_type TEXT NOT NULL, title TEXT NOT NULL, lesson TEXT NOT NULL, standard_practice TEXT NOT NULL, evidence_note TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PROPOSED', owner_user_id TEXT, due_date DATE, approved_by TEXT, approved_at TIMESTAMP, resolved_by TEXT, resolved_at TIMESTAMP, created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_rel_gov_learning_closure_scope ON maintenance_reliability_governance_learning_closure(organization_id,entity_id,period_key);
CREATE INDEX IF NOT EXISTS ix_rel_gov_learning_knowledge_scope ON maintenance_reliability_governance_learning_knowledge(organization_id,entity_id,period_key,status);
